<?php
declare(strict_types=1);
function documentSnapshot(PDO $pdo,string $documentId):array{$q=$pdo->prepare('SELECT * FROM requirement_documents WHERE id=?');$q->execute([$documentId]);$document=$q->fetch(PDO::FETCH_ASSOC)?:[];$q=$pdo->prepare('SELECT id,editor_block_id,block_type,content,sort_order FROM requirement_document_blocks WHERE document_id=? ORDER BY sort_order,id');$q->execute([$documentId]);$blocks=$q->fetchAll(PDO::FETCH_ASSOC);foreach($blocks as &$block){$decoded=json_decode((string)($block['content']??''),true);$block['content']=json_last_error()===JSON_ERROR_NONE?$decoded:$block['content'];}unset($block);return ['document'=>$document,'blocks'=>$blocks];}
function documentWriteHistory(PDO $pdo,array $snapshot,string $action,int $userId,?array $oldSnapshot=null):void{$document=$snapshot['document']??[];$documentId=(string)($document['id']??'');$projectId=(string)($document['project_id']??'');$key=(string)($document['requirement_key']??$documentId);$title=(string)($document['title']??'');$revision=max(1,(int)($document['revision']??1));$q=$pdo->prepare('INSERT INTO requirement_document_revisions(document_id,project_id,requirement_key,title,revision,action,snapshot,created_by)VALUES(?,?,?,?,?,?,?,?)');$q->execute([$documentId,$projectId,$key,$title,$revision,$action,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$userId]);$changed=[];if($oldSnapshot){$old=$oldSnapshot['document']??[];foreach(['title','status','priority','relevance','review_status','revision','metadata']as$field)if(($old[$field]??null)!==($document[$field]??null))$changed[]=$field;if(($oldSnapshot['blocks']??[])!==($snapshot['blocks']??[]))$changed[]='blocks';}$q=$pdo->prepare('INSERT INTO audit_log(project_id,entity_type,entity_id,entity_key,entity_title,action,old_data,new_data,changed_fields,actor_user_id,actor_name,source_type,source_name,hostname,request_id,created_at)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)');$q->execute([$projectId,'requirement_document',$documentId,$key,$title,strtoupper($action),$oldSnapshot?json_encode($oldSnapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),json_encode($changed,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$userId,$_SESSION['username']??null,'web',basename($_SERVER['SCRIPT_NAME']??'document_studio_v4.php'),gethostname()?:'unbekannt',bin2hex(random_bytes(16))]);}
